local UIMazeStoryEventDialog = Class("UIMazeStoryEventDialog")

function UIMazeStoryEventDialog:__init() 
    self.point = nil            --点
    self.optionSelectIndex = nil   --当前选中的条件id
    self.storyCf = nil    --迷宫剧情事件表

    --总共有俩种选项
    self.optionTab = {
        [1] = 1,
        [2] = 2,
    }
end

function UIMazeStoryEventDialog:__delete()
    self.point = nil            --点
    self.optionSelectIndex = nil   --当前选中的条件id
    self.storyCf = nil    --迷宫剧情事件表

    --总共有俩种选项
    self.optionTab = {
        [1] = 1,
        [2] = 2,
    }
end

function UIMazeStoryEventDialog:OnFocus(focus)
    if focus then
        self:ShowCommonTop()
    end
end

function UIMazeStoryEventDialog:Awake()
    local pars = self.controller.Argument.parameters   --界面传参
    self.point = pars.point
    if not self.point then return end

    self.storyId = self.point.eventId
    if not self.storyId then
        return
    end 

    self.storyCf = CfUtils.GetCfVo(AutoIds.IdSetting356, "MazeStoryVo", self.storyId)
    if not self.storyCf then
        return
    end

    self:FillSelfCf()
    self:FillSelf()

    local animator = self.Root.gameObject:GetComponent(typeof(Animator))
    animator:Play("UIMazeStoryEventDialog_home")
end

function UIMazeStoryEventDialog:ShowCommonTop()
    CfUtils.RefreshTopCommon(function()
        self:OnbtnClose()
    end, false)
    CfUtils.RefreshTopCommonEntrance()
end


function UIMazeStoryEventDialog:FillSelfCf()
    SetButtonAction(self.btnClose, Bind(self, self.OnbtnClose))

    CfUtils.FillText(self.cfText1, localize("谨慎选择，做对了有奖励，做错了有惩罚"))
    CfUtils.FillText(self.cfText2, localize("事件详情"))
    CfUtils.FillText(self.cfText3, localize("请选择行动"))
    CfUtils.FillText(self.btnChoose.transform:Find("MainTxt"), localize("确认选择"))
    CfUtils.FillText(self.cfText7, localize("点击任意位置继续"))
end

function UIMazeStoryEventDialog:FillSelf()
    self:FillTitle()
    CfUtils.FillText(self.desc, self.storyCf.desc2)

    --目前只有俩个选项
    for i = 1, #self.optionTab do
        local go = CfUtils.InstantiateGo(self.optionGo, self.chooseContent)
        self:FillOption(go, i)
        KTool.SetActive(go, true)
    end
end

--标题
function UIMazeStoryEventDialog:FillTitle()
    CfUtils.FillText(self.curPointText, checkNumber(self.point.line) - 1 < 10 and "0"..self.point.line - 1 or self.point.line - 1)
    CfUtils.FillText(self.allPointText, "/"..MazeMapMgr:GetInstance():GetMaxLineNum())
    
    local eventType = self.point.type
    CfUtils.FillText(self.name, self.storyCf.name)
    self.img.color = CfUtils.GetMazeCommonColor(self.point.type)
    CfUtils.FillImage(self.typeImg, CfUtils.GetMazePreviewPath(self.point))
    self.loader = CfUtils.FillEnentAnim(self.typeImg, self.point)
end

--绘制选项
function UIMazeStoryEventDialog:FillOption(go, optionIndex)
    if not go then
        return
    end

    local scr = CfUtils.GetLuaScr(go, UIMazeStoryEventOptionNode)
    if scr then
        scr:Refresh(self.storyCf, optionIndex, function(value)
            if value then
                self.optionSelectIndex = optionIndex
                self:FillBtnChoose()
            end
        end)
    end
end

--绘制选择完之后的结果
--resultData  服务器返回的结果数据
function UIMazeStoryEventDialog:FillResult(resultData)
    if resultData then
        local scr = CfUtils.GetLuaScr(self.resultGo1, UIMazeStoryEventResultNode)
        if scr then
            scr:RefreshTitle(self:GetResultDes())
        end

        --奖励类型
        local rewardType = 0
        if checkNumber(self.optionSelectIndex) == self.optionTab[1] then
            rewardType = checkNumber(self.storyCf.type1)
        else
            rewardType = checkNumber(self.storyCf.type2)
        end

        if rewardType == Constants.MazeRewardType.MazeCurses then
            CfUtils.FillImage(self.effectIma, "uiatlas/Maze/MazeStory/maze_event_img_result_bad.png")
        else
            CfUtils.FillImage(self.effectIma, "uiatlas/Maze/MazeStory/maze_event_img_result_good.png")
        end

        scr = CfUtils.GetLuaScr(self.resultGo2, UIMazeStoryEventResultNode)
        if scr then
            scr:RefreshEffect(rewardType, resultData)
        end
    end 
end

function UIMazeStoryEventDialog:GetResultDes()
    if not self.storyCf then
        return "" 
    end
    if checkNumber(self.optionSelectIndex) == self.optionTab[1] then
        return checkString(self.storyCf.desc3)
    else
        return checkString(self.storyCf.desc4)
    end
end

--绘制选择按钮
function UIMazeStoryEventDialog:FillBtnChoose()
    if self.isFillBtnChoose then
        return
    end
    self.isFillBtnChoose = true
    KTool.SetActive(self.btnChoose, true)
    SetButtonAction(self.btnChoose, Bind(self, self.OnbtnChoose))
end

function UIMazeStoryEventDialog:OnbtnChoose()
    if not self.optionSelectIndex then
        GameUtils.Toast(localize("需要选择事件"))
        return
    end

    MazeMgr:GetInstance():MazeMoveToEvent(self.point, self.optionSelectIndex, function(resultData)
        self:FillResult(resultData)

        KTool.SetActive(self.left, false)
        KTool.SetActive(self.btnChoose, false)

        KTool.SetActive(self.resultShow, true)
        local animator = self.Root.gameObject:GetComponent(typeof(Animator))
        animator:Play("UIMazeStoryEventDialog")
    end)
end

function UIMazeStoryEventDialog:OnbtnClose()
    MazeMgr:GetInstance():OpenMazeMainGameObject()
    UIModule.CloseDialog(self.controller)
end

